import React from "react";
import { motion } from "framer-motion";
import { TESTIMONIALS } from "./Content";
import { Quote, Star } from "lucide-react";

// Glass card animation variants
const cardVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    transition: { delay: i * 0.1, duration: 0.5, ease: "easeOut" }
  }),
  hover: {
    y: -8,
    boxShadow: "0 20px 60px rgba(212, 175, 55, 0.2), 0 0 40px rgba(212, 175, 55, 0.1)",
    borderColor: "rgba(212, 175, 55, 0.5)",
    transition: { duration: 0.3, ease: "easeOut" }
  }
};

// Star animation variants
const starVariants = {
  hidden: { opacity: 0, scale: 0 },
  visible: (i) => ({
    opacity: 1,
    scale: 1,
    transition: { delay: i * 0.08, duration: 0.3, type: "spring", stiffness: 200 }
  })
};

export default function Testimonials() {
  const items = [...TESTIMONIALS, ...TESTIMONIALS];

  return (
    <section id="reviews" className="relative py-20 md:py-28 overflow-hidden" style={{ background: "#fdf8ed" }}>
      {/* Decorative background elements */}
      <motion.div
        className="absolute top-0 left-0 w-96 h-96 rounded-full pointer-events-none"
        style={{
          background: "radial-gradient(circle, rgba(212, 175, 55, 0.08) 0%, transparent 70%)",
          filter: "blur(60px)"
        }}
        animate={{
          scale: [1, 1.1, 1],
          opacity: [0.5, 0.8, 0.5]
        }}
        transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }}
      />
      <motion.div
        className="absolute bottom-0 right-0 w-80 h-80 rounded-full pointer-events-none"
        style={{
          background: "radial-gradient(circle, rgba(212, 175, 55, 0.06) 0%, transparent 70%)",
          filter: "blur(60px)"
        }}
        animate={{
          scale: [1, 1.15, 1],
          opacity: [0.4, 0.7, 0.4]
        }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut", delay: 2 }}
      />

      <div className="max-w-7xl mx-auto px-6 md:px-12 lg:px-32 relative z-10">
        <motion.div
          className="mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="flex items-center gap-3 mb-6">
            <motion.div
              className="w-12 h-px"
              style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }}
              initial={{ width: 0 }}
              whileInView={{ width: 48 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6 }}
            />
            <span className="overline font-bold tracking-[0.4em]">Testimonials</span>
          </div>
          <h2 style={{ fontSize: "clamp(40px, 5vw, 64px)", lineHeight: 1.05, color: "#1a080a", fontFamily: "Outfit, sans-serif", fontWeight: 800, maxWidth: 700 }}>
            What decorators across India <span style={{ color: "#d4af37", fontWeight: 800 }}>keep saying</span>.
          </h2>
        </motion.div>

        <div className="relative">
          {/* Gradient fades for horizontal scroll */}
          <motion.div
            className="absolute left-0 top-0 bottom-0 w-32 z-10 pointer-events-none"
            style={{ background: "linear-gradient(to right, #fdf8ed, transparent)" }}
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
          />
          <motion.div
            className="absolute right-0 top-0 bottom-0 w-32 z-10 pointer-events-none"
            style={{ background: "linear-gradient(to left, #fdf8ed, transparent)" }}
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
          />

          <motion.div
            className="marquee py-2"
            whileHover={{ animationPlayState: "paused" }}
          >
            {items.map((t, i) => (
              <motion.article
                key={i}
                className="p-7 md:p-9 flex-shrink-0 testimonial-card"
                style={{ width: 480 }}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={i}
                variants={cardVariants}
                whileHover="hover"
              >
                {/* Quote icon with glow */}
                <motion.div
                  initial={{ rotate: -10, opacity: 0 }}
                  whileInView={{ rotate: 0, opacity: 1 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.05 + 0.2, duration: 0.4 }}
                  className="mb-4"
                >
                  <div className="relative inline-block">
                    <motion.div
                      className="absolute inset-0 rounded-full"
                      style={{ background: "rgba(212, 175, 55, 0.2)", filter: "blur(10px)" }}
                      animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
                      transition={{ duration: 3, repeat: Infinity }}
                    />
                    <Quote size={32} strokeWidth={1.4} style={{ color: "#d4af37", position: "relative" }} />
                  </div>
                </motion.div>

                <p className="serif" style={{ color: "#1a080a", fontSize: 18, lineHeight: 1.6, fontWeight: 400, minHeight: 100 }}>
                  "{t.quote}"
                </p>

                <div className="mt-6 flex items-center justify-between">
                  <div>
                    <motion.div
                      style={{ color: "#1a080a", fontWeight: 600, letterSpacing: "0.02em" }}
                      whileHover={{ color: "#d4af37", x: 5 }}
                      transition={{ duration: 0.2 }}
                    >
                      {t.name}
                    </motion.div>
                    <div className="text-xs mt-1" style={{ color: "rgba(26,8,10,0.6)" }}>{t.role} - {t.city}</div>
                  </div>

                  {/* Animated stars */}
                  <motion.div
                    className="flex items-center gap-0.5"
                    initial="hidden"
                    whileInView="visible"
                    viewport={{ once: true }}
                  >
                    {[...Array(5)].map((_, idx) => (
                      <motion.div
                        key={idx}
                        custom={idx}
                        variants={starVariants}
                      >
                        <Star
                          size={16}
                          fill="#d4af37"
                          color="#d4af37"
                          strokeWidth={0}
                        />
                      </motion.div>
                    ))}
                  </motion.div>
                </div>

                {/* Verified badge */}
                <motion.div
                  className="mt-5 inline-flex items-center gap-2 text-[10px] tracking-[0.22em] uppercase font-semibold"
                  style={{ color: "#d4af37" }}
                  initial={{ opacity: 0, y: 10 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.05 + 0.4, duration: 0.3 }}
                  whileHover={{ scale: 1.05 }}
                >
                  <motion.span
                    className="w-2 h-2 rounded-full"
                    style={{ background: "#22c55e" }}
                    animate={{ scale: [1, 1.2, 1], opacity: [1, 0.7, 1] }}
                    transition={{ duration: 2, repeat: Infinity }}
                  />
                  Verified Customer
                </motion.div>

                {/* Decorative corner accent */}
                <div
                  className="absolute top-0 right-0 w-16 h-16 pointer-events-none"
                  style={{
                    background: "linear-gradient(135deg, transparent 50%, rgba(212, 175, 55, 0.1) 50%)",
                    borderTopRightRadius: "0.75rem"
                  }}
                />
              </motion.article>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
